------------ import ------------
local Decorator = import("Frame.AI.BT.Decorators.Decorator")
------------ import ------------

------------ define ------------
local TaskStatus = Decorator.TaskStatus
------------ define ------------

---@class Inverter
local Inverter = Class("Inverter", Decorator)

function Inverter:Update(context)
    assert(self._child ~= nil, "child 不能为空")

    local status = self._child:Update(context)
    if status == TaskStatus.Success then
        return TaskStatus.Failure
    end

    if status == TaskStatus.Failure then
        return TaskStatus.Success
    end

    return TaskStatus.Running
end


return Inverter
 